import {ramp,smooth} from './svg.js';
export const duration=34;
export const info={shortTitle:'Bosch 深矽蝕刻',title:'Bosch 深矽蝕刻｜向下挖深並保護側壁',label:'固定矽槽剖面三輪鈍化、底部開膜、矽蝕刻，累積深度與波紋',overview:28,summary:'Bosch代表模型：C₄F₈形成氟碳聚合物鈍化膜，方向性離子優先移除底膜，SF₆電漿含氟活性物種反應移除露出矽；含矽揮發產物以SiF₄示意。起始已有硬遮罩及短槽，遮罩材料不指定為所有設備共用配方。三輪波紋、膜厚與時間大幅放大，粒子數不代表化學計量。矽蝕刻的局部較等向擴展以圓滑波紋示意，不是只向下刪矩形。上方側壁膜會耗損與補充，新蝕出的槽壁待下一輪覆膜；最後殘膜留待後續清理。省略遮罩緩慢消耗、微觀表面反應、載入效應與設備切換過渡，不包含填銅、背面露出或TSV接點。',sources:[{title:'Samco — What is the Bosch Process?',url:'https://www.samcointl.com/news-events/tutorials/what-is-the-bosch-process/',note:'覆膜、開底膜、蝕刻三動作與氣體。'},{title:'Fraunhofer ISIT — DRIE',url:'https://www.isit.fraunhofer.de/en/technology/micro-manufacturing-processes/processes-on-wafer-level/drie.html',note:'方向性開膜與底部局部蝕刻。'},{title:'Samco Technical Report 82',url:'https://www.samcointl.com/tech_notes/pdf/Technical_Report_82.pdf',note:'交替製程與側壁scallop。'},{title:'JVST A — Tutorial on forming through-silicon vias',url:'https://pubs.aip.org/avs/jva/article/38/3/031202/1023659/Tutorial-on-forming-through-silicon-vias',note:'側壁保護、底膜去除與加工後聚合物殘留；只採蝕刻原理。'}],supplement:'<details><summary>補充：兩段配方與三個動作</summary><p>設備常以沉積／蝕刻交替運作；打開底膜可包含在蝕刻步驟前段。動畫把三個可觀察動作分開，不宣稱所有機台採三段配方。</p><p>方向性離子優先作用水平底膜，側壁膜相對保留。含氟物種在底部開放後才繼續蝕矽，局部側向擴展形成波紋。保護膜不是永久不變的外殼。</p></details>'};
export const stages=[{at:0,key:1,title:'硬遮罩與短初始槽',what:'中央開口對準已有短槽，追蹤同一塊矽。',detail:'後續三輪累積深度，不重設前輪幾何。'},...Array.from({length:3},(_,i)=>[{at:3+8*i,key:5.8+8*i,title:`第${i+1}輪：覆蓋鈍化膜`,what:'C₄F₈來源形成氟碳固體薄膜，覆蓋側壁與底部。',detail:'前輪殘膜補充；剛蝕出的新壁也在本輪覆膜。'},{at:6+8*i,key:7.8+8*i,title:`第${i+1}輪：打開底膜`,what:'方向性離子優先清除水平底膜，側壁膜相對保留。',detail:'底膜尚未開放時，矽槽深度不增加。'},{at:8+8*i,key:10.9+8*i,title:`第${i+1}輪：蝕刻露出的矽`,what:'含氟活性物種反應移除底部矽，揮發產物排出。',detail:'局部擴展形成波紋，前輪深度及側壁持續保留。'}]).flat(),{at:27,key:28,title:'停機，殘膜待清理',what:'深槽已形成，較早的側壁仍有氟碳殘膜。',detail:'本題不執行後續清理，不暗示殘膜自動消失。'},{at:30,key:31,title:'完成件退出',what:'深槽基板離開，新開口短槽基板進場。',detail:'內部三輪累積深度；整片換料後才開始新作品循環。'}];
export function state(t){const k=Math.min(2,Math.max(0,Math.floor((t-3)/8))),local=t-3-8*k;return{t,index:Math.max(0,stages.findLastIndex(x=>t>=x.at)),k,local,phase:t<3?'idle':t>=27?'stop':local<3?'coat':local<5?'open':'etch',coat:ramp(local,0,3),open:ramp(local,3,5),etch:ramp(local,5,8),depths:[0,1,2].map(i=>ramp(t,8+8*i,11+8*i)),out:smooth(ramp(t,30,32)),incoming:smooth(ramp(t,32,34)),newWafer:t>=32};}
